def test_get_workflow_summary_negative_params(api_client, get_config):
    """
    Negative parameter scenarios: conflicting query params, invalid types, and nonexistent resources.
    Validated against the 'default' error response schema.
    """
    token: str = get_config("auth.api_key_header", "")
    if not token:
        pytest.skip("auth.api_key_header is not set in config.yml (Circle-Token).")

    project_slug: str = get_config("test_data.project-slug", "")
    workflow_name: str = get_config("test_data.workflow-name", "")
    if not project_slug or not workflow_name:
        pytest.skip("Missing required test_data.project-slug or test_data.workflow-name in config.yml")

    validator = SwaggerSchemaValidator("api.json")
    path = _format_path(_ENDPOINT, project_slug, workflow_name)

    # 1) Both branch and all-branches provided (mutually exclusive by description)
    headers = {"Circle-Token": token}
    params_conflict = {"branch": "main", "all-branches": True}
    resp_conflict = api_client.get(path, headers=headers, params=params_conflict)
    assert not (200 <= resp_conflict.status_code < 300), (
        f"Expected non-2xx for conflicting params; got {resp_conflict.status_code}"
    )
    res_conflict = validator.validate_schema_by_response(_ENDPOINT, _METHOD, "default", resp_conflict)
    assert res_conflict.get("valid"), f"Default error schema invalid (conflicting params): {res_conflict}"

    # 2) Invalid type for all-branches (expects boolean)
    params_bad_type = {"all-branches": "not-a-boolean"}
    resp_bad_type = api_client.get(path, headers=headers, params=params_bad_type)
    assert not (200 <= resp_bad_type.status_code < 300), (
        f"Expected non-2xx for invalid param type; got {resp_bad_type.status_code}"
    )
    res_bad_type = validator.validate_schema_by_response(_ENDPOINT, _METHOD, "default", resp_bad_type)
    assert res_bad_type.get("valid"), f"Default error schema invalid (bad type): {res_bad_type}"

    # 3) Nonexistent workflow name to simulate not found or forbidden
    invalid_path = _format_path(_ENDPOINT, project_slug, f"{workflow_name}-nonexistent")
    resp_not_found = api_client.get(invalid_path, headers=headers, params={})
    assert not (200 <= resp_not_found.status_code < 300), (
        f"Expected non-2xx for nonexistent workflow; got {resp_not_found.status_code}"
    )
    res_not_found = validator.validate_schema_by_response(_ENDPOINT, _METHOD, "default", resp_not_found)
    assert res_not_found.get("valid"), f"Default error schema invalid (not found): {res_not_found}"
